def parse_block_math(block: 'BlockParser', m: Match[str], state: 'BlockState'
    ) ->int:
    text = m.group("math_text")
    state.append_token({"type": "block_math", "raw": text})
    return m.end()


def math(md: 'Markdown') ->None:
    md.block.register('block_math', BLOCK_MATH_PATTERN, parse_block_math)
    md.inline.register('inline_math', INLINE_MATH_PATTERN, parse_inline_math)
    md.add_render_rule('block_math', render_block_math)
    md.add_render_rule('inline_math', render_inline_math)


def math_in_quote(md: 'Markdown') ->None:
    md.block.insert_rule(md.block.quote_rules, 'block_math', before='paragraph')
